                        if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny,nx]==c:
                            seen.add((ny,nx)); st.append((ny,nx))
                mn=min(q[0] for q in cells); mni=min(q[1] for q in cells)
                res.append({'c':c,'mr':mn,'mc':mni,'cells':set(map(tuple,cells)),'hh':max(q[0] for q in cells)-mn+1,'ww':max(q[1] for q in cells)-mni+1})
